import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        s = next(iterator)
        n = len(s)

        if n % 2 != 0:
            results.append("NO")
            continue

        target = n // 2

        open_count = 0
        close_count = 0
        balance = 0
        possible = True

        for char in s:
            if char == '(':
                open_count += 1
                balance += 1
            elif char == ')':
                close_count += 1
                balance -= 1
            else:
                pass

            if balance < 0:
                possible = False
                break

        if not possible:
            results.append("NO")
            continue

        if open_count > target or close_count > target:
            results.append("NO")
            continue

        remaining = n - open_count - close_count
        needed_open = target - open_count
        needed_close = target - close_count

        if needed_open < 0 or needed_close < 0:
            results.append("NO")
            continue

        current_balance = 0
        possible = True

        for i, char in enumerate(s):
            if char == '(':
                current_balance += 1
            elif char == ')':
                current_balance -= 1
            else:
                if needed_open > 0:
                    current_balance += 1
                    needed_open -= 1
                else:
                    current_balance -= 1

            if current_balance < 0:
                possible = False
                break

        if possible and current_balance == 0:
            results.append("YES")
        else:
            results.append("NO")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
